"""Validation and provenance for datasets generated by our RTL graph pipeline."""
import hashlib
import json
from pathlib import Path

import torch

from rtl_graph import GRAPH_SPEC, NODE_TYPES, EDGE_ROLES, fingerprint


def file_hash(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


json_hash = fingerprint


def validate_graph(graph, *, mask_ratio=0.2):
    x, edges, y, pe = graph.x, graph.edge_index, graph.y, graph.pos_enc
    classes = len(NODE_TYPES)
    if x.ndim != 2 or x.shape[1] != classes + 1 or x.shape[0] < 2 or x.dtype != torch.float32:
        raise ValueError(f"x must be float32 with shape [N, {classes + 1}], N >= 2")
    n = x.shape[0]
    if y.shape != (n, 1) or y.dtype != torch.long:
        raise ValueError("y must be int64 with shape [N, 1]")
    if pe.shape != (n, 16) or pe.dtype != torch.float32:
        raise ValueError("pos_enc must be float32 with shape [N, 16]")
    if not all(torch.isfinite(t).all().item() for t in (x, pe)):
        raise ValueError("node features and positions must be finite")
    types = y[:, 0]
    if not ((types >= 0) & (types < classes)).all():
        raise ValueError(f"node types must be IDs in [0, {classes - 1}]")
    onehot = torch.nn.functional.one_hot(types, classes).float()
    if not torch.equal(x[:, :classes], onehot):
        raise ValueError("node-type one-hot features must match y[:, 0]")
    if not ((x[:, -1] > 0) & (x[:, -1] == x[:, -1].round())).all():
        raise ValueError("graph widths must be positive integers")
    if edges.ndim != 2 or edges.shape[0] != 2 or edges.dtype != torch.long:
        raise ValueError("edge_index must be int64 with shape [2, E]")
    if edges.shape[1] == 0 or not ((edges >= 0) & (edges < n)).all():
        raise ValueError("graph must contain edges with valid endpoints")
    if not 0 < mask_ratio <= 1:
        raise ValueError("mask ratio must be in (0, 1]")
    pairs = set(map(tuple, edges.t().tolist()))
    if sum(u != v for u, v in pairs) >= n * (n - 1):
        raise ValueError("graph has no possible negative directed edges")
    edge_attr = getattr(graph, "edge_attr", None)
    if edge_attr is None or edge_attr.shape != (edges.shape[1], 1) or edge_attr.dtype != torch.long:
        raise ValueError("edge_attr must be int64 with shape [E, 1]")
    if not ((edge_attr >= 0) & (edge_attr < len(EDGE_ROLES))).all():
        raise ValueError("edge_attr contains an invalid role")
    pins = getattr(graph, "edge_ports", [])
    if len(pins) != edges.shape[1] or not all(isinstance(pin, str) and pin for pin in pins):
        raise ValueError("edge_ports must provide a pin identity for each edge")
    if len(getattr(graph, "node_parameters", [])) != n:
        raise ValueError("node_parameters must provide metadata for each node")
    if getattr(graph, "graph_schema", None) != GRAPH_SPEC["name"]:
        raise ValueError("Unsupported graph schema; original StructRTL graphs cannot be mixed in")


def validate_contract(metadata):
    contract = metadata.get("preprocessing", {})
    if metadata.get("schema_version") != 2 or contract.get("graph_spec") != GRAPH_SPEC:
        raise ValueError("Unsupported dataset/checkpoint schema; regenerate graphs with prepare_data.py")
    if not contract.get("yosys_version") or metadata.get("preprocessing_fingerprint") != json_hash(contract):
        raise ValueError("Preprocessing fingerprint does not match its contract")


def dataset_statistics(datasets):
    result = {}
    for split, graphs in datasets.items():
        counts = torch.zeros(len(NODE_TYPES), dtype=torch.long)
        for graph in graphs:
            counts += torch.bincount(graph.y[:, 0], minlength=len(NODE_TYPES))
        result[split] = dict(graphs=len(graphs), nodes=sum(g.num_nodes for g in graphs),
                             edges=sum(g.num_edges for g in graphs), class_counts=counts.tolist())
    return result


def load_datasets(directory, *, mask_ratio=0.2):
    directory = Path(directory)
    sidecar = directory / "dataset.json"
    if not sidecar.exists():
        raise ValueError("Missing dataset.json: assemble our generated graphs first; legacy datasets are unsupported")
    metadata = json.loads(sidecar.read_text())
    validate_contract(metadata)
    hashes = {split: file_hash(directory / f"{split}.pt") for split in ("train", "val")}
    if metadata.get("files") != hashes or metadata.get("dataset_fingerprint") != json_hash(
        {"files": hashes, "preprocessing_fingerprint": metadata["preprocessing_fingerprint"],
         "designs": metadata.get("designs", []), "family_splits": metadata.get("family_splits", {})}
    ):
        raise ValueError("Dataset content does not match dataset.json")
    datasets = {}
    for split in ("train", "val"):
        graphs = torch.load(directory / f"{split}.pt", weights_only=False, map_location="cpu")
        if not isinstance(graphs, (list, tuple)) or not graphs:
            raise ValueError(f"{split}: expected a nonempty graph list")
        for index, graph in enumerate(graphs):
            try:
                validate_graph(graph, mask_ratio=mask_ratio)
            except (ValueError, AttributeError, RuntimeError) as exc:
                raise ValueError(f"{split}[{index}]: {exc}") from exc
        datasets[split] = graphs
    entries = metadata.get("designs", [])
    seen, families = set(), {}
    for split, graphs in datasets.items():
        records = [entry for entry in entries if entry.get("split") == split]
        if len(records) != len(graphs):
            raise ValueError(f"{split}: incomplete design provenance")
        for index, (record, graph) in enumerate(zip(records, graphs)):
            design_id = record.get("design_id")
            family = record.get("project_family")
            if not design_id or not family or design_id in seen or record.get("index") != index:
                raise ValueError("Invalid or duplicate design identity")
            if design_id != getattr(graph, "design_id", None):
                raise ValueError("Graph identity does not match dataset provenance")
            seen.add(design_id)
            if family in families and families[family] != split:
                raise ValueError("Project family crosses train/validation split")
            families[family] = split
            if metadata.get("family_splits", {}).get(family) != split:
                raise ValueError("Persisted family assignments do not match design records")
    if len(entries) != len(seen):
        raise ValueError("Unexpected design records in dataset manifest")
    if metadata.get("statistics") != dataset_statistics(datasets):
        raise ValueError("Dataset statistics do not match graphs")
    return datasets["train"], datasets["val"], metadata
